args.sparql:
SELECT ?father ?fatherLabel WHERE { 
  dbr:Saw_E dbp:father ?father .
  OPTIONAL { ?father rdfs:label ?fatherLabel . FILTER(langMatches(lang(?fatherLabel), "en")) }
} LIMIT 10

SELECT ?paternalGrandfather ?paternalGrandfatherLabel WHERE {
  dbr:Saw_E dbp:father ?father .
  ?father dbp:father ?paternalGrandfather .
  OPTIONAL { ?paternalGrandfather rdfs:label ?paternalGrandfatherLabel . FILTER(langMatches(lang(?paternalGrandfatherLabel), "en")) }
} LIMIT 10

SELECT ?paternalGrandfather ?paternalGrandfatherLabel WHERE {
  dbr:Saw_E dbp:father ?father .
  ?father dbp:father ?paternalGrandfather .
  OPTIONAL { ?paternalGrandfather rdfs:label ?paternalGrandfatherLabel . FILTER(langMatches(lang(?paternalGrandfatherLabel), "en")) }
} LIMIT 10

output.sparql:
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
SELECT ?paternalGrandfather ?paternalGrandfatherLabel WHERE {
  dbr:Saw_E dbp:father ?father .
  ?father dbp:father ?paternalGrandfather .
  OPTIONAL {
    ?paternalGrandfather rdfs:label ?paternalGrandfatherLabel .
    FILTER(langMatches(lang(?paternalGrandfatherLabel) , "en"))
  }
}
LIMIT 10

